/**
 * server.js
 * Universal HTTP server and Vercel Serverless Function handler for TaskFlow.
 * 
 * Guarantees 100% asset delivery across all environments:
 * 1. Local Development (node server.js / npm start) -> Live read from disk
 * 2. Vercel Serverless Function -> Embedded asset dictionary prevents any NFT 404s
 * 3. Vercel Edge CDN -> Public directory static hosting
 */

